import json
from typing import Literal

from pyvkteamsclient.admin.base.client import BaseAdminClient
from pyvkteamsclient.tracer import tracer


class ExpoMethods(BaseAdminClient):
    @tracer.start_as_current_span("admin.expo.api_expo_get")
    def api_expo_get(
        self,
        type_: Literal["bot", "group", "channel"],
        sort: tuple[
            Literal["position", "name", "stamp", "type", "members_count", "created"],
            Literal["asc", "desc"],
        ] = ("position", "asc"),
        offset: int = 0,
        limit: int = 0,
    ):
        return self.get(
            path="api/expo",
            type=type_,
            sort=json.dumps(sort),
            offset=offset,
            limit=limit,
        )

    @tracer.start_as_current_span("admin.expo.api_expo_post")
    def api_expo_post(self, chat_id: str):
        return self.post(path="api/expo", data={"id": chat_id})

    @tracer.start_as_current_span("admin.expo.api_expo_put")
    def api_expo_put(self, chat_id: str, position: int):
        return self.put(path=f"api/expo/{chat_id}", data={"position": position})

    @tracer.start_as_current_span("admin.expo.api_expo_delete")
    def api_expo_delete(self, chat_id: str):
        return self.delete(path=f"api/expo/{chat_id}")

    @tracer.start_as_current_span("admin.expo.api_expo_download")
    def api_expo_download(
        self,
        type_: Literal["bot", "group", "channel"],
        sort: str = ("created", "asc"),
        offset: int = 0,
        limit: int = 0,
    ):
        return self.get(
            path="api/expo/download",
            type=type_,
            sort=json.dumps(sort),
            offset=offset,
            limit=limit,
        )
